    if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
        points += 1;
    }
    if (householdSize(owner) >= 3) {
        points += 2;
    }
    if (tenureDays(owner) > 365) {
        points += 3;
    }
    return points;
}

/**
 * Maps the owner's {@link #membershipPoints(Owner) membership points} to a numeric level:
 * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
 */
public int membershipLevel(Owner owner) {
    int points = membershipPoints(owner);
    if (points <= 1) {
        return 1;
    }
    if (points <= 3) {
        return 2;
    }
    if (points <= 5) {
        return 3;
    }
    return 4;
}

/**
 * The number of owners that belong to this owner's household, counted at read time by its
 * {@code householdId}. Returns 0 when the owner belongs to no household (no {@code householdId}),
 * so such an owner never earns the household points.
 */
public long householdSize(Owner owner) {
    String householdId = owner.getHouseholdId();
    if (householdId == null || householdId.isBlank()) {
        return 0;
    }
    long count = 0;
    for (Owner existing : ownerRepository.findAll()) {
        if (householdId.equals(existing.getHouseholdId())) {
            count++;
        }
    }
    return count;
}

